mod tests {
    use super::*;

    fn vc(runtime: Option<&str>) -> VerifyConfig {
        VerifyConfig {
            runtime: runtime.map(str::to_string),
            image: "img".into(),
            cache: "c".into(),
            egress: bridge_core::domain::EgressPolicy::Open,
